function SeparateParenGroups(parenString: string): array of string;
begin
  var groups := new List<string>;
  var stack := new Stack<char>;

  for var i := 1 to parenString.Length do
  begin
    if parenString[i] = ' ' then
      continue;

    if parenString[i] = '(' then
      stack.Push(parenString[i])
    else if parenString[i] = ')' then
    begin
      var group := '';
      while stack.Count > 0 do
      begin
        group := stack.Pop.ToString + group;
        if stack.Count = 0 then
          break;
        group := stack.Pop.ToString + group;
      end;
      groups.Add(group);
    end;
  end;

  Result := groups.ToArray;
end;

begin
end.




