function Modp(n, p: integer): integer;
begin
  if n = 0 then
  begin
    Result := 1;
    exit;
  end;

  var res := 1;
  var n := Abs(n);

  while n > 0 do
  begin
    if n and 1 = 1 then
      res := res mod p;
    n := n shr 1;
  end;

  if n < 0 then
    Result := -res
  else
    Result := res;
end;

