function Add(x, y: integer): integer;
begin
  if (x = 0) and (y = 0) then
  begin
    Result := 0;
    exit;
  end;

  if (y = 0) then
  begin
    Result := x;
    exit;
  end;

  var carry := 0;
  var sum := 0;

  while (y <> 0) do
  begin
    var temp := x and y;
    sum := temp shl 1;
    carry := x and y;
    x := carry shl 1;
    y := carry;
  end;

  Result := sum;
end;

begin
end.




