  if l.Length = 0 then
  begin
    Result := True;
    exit;
  end;

  var increasing := l[0] < l[1];
  for var i := 2 to l.Length - 1 do
  begin
    if (l[i] < l[i-1]) <> increasing then
    begin
      Result := False;
      exit;
    end;
  end;

  Result := True;
end;

begin
end.




function Common(l1, l2: array of integer): array of integer;
begin
  var common := new List<integer>;
  var h1 := new HashSet<integer>(l1);
  var h2 := new HashSet<integer>(l2);

  foreach var num in l1 do
    if h2.Contains(num) then
      common.Add(num);

  common.Sort;
  Result := common.ToArray;
end;

begin
end.




function LargestPrimeFactor(n: integer): integer;
begin
  var i := 2;
  while i * i <= n do
  begin
    if n mod i = 0 then
    begin
      n := n div i;
    end
    else
      i += 1;
  end;
  Result := n;
end;

begin
end.




