function Fibfib(n: integer): integer;
begin
  if n = 0 then
  begin
    Result := 0;
    exit;
  end;
  if n = 1 then
  begin
    Result := 0;
    exit;
  end;
  if n = 2 then
  begin
    Result := 1;
    exit;
  end;
  var fibfib := new integer[n + 1];
  fibfib[0] := 0;
  fibfib[1] := 0;
  fibfib[2] := 1;
  for var i := 3 to n do
    fibfib[i] := fibfib[i - 1] + fibfib[i - 2] + fibfib[i - 3];
  Result := fibfib[n];
end;

begin
end.




