function Pluck(arr: array of integer): array of integer;
begin
  var evenList := new List<integer>;
  foreach var num in arr do
    if num mod 2 = 0 then
      evenList.Add(num);

  if evenList.Count = 0 then
  begin
    Result := new integer[0];
    exit;
  end;

  var smallestEven := evenList.Min;
  var smallestIndex := arr.IndexOf(smallestEven);

  Result := new integer[2];
  Result[0] := smallestEven;
  Result[1] := smallestIndex;
end;

