end.




function Search(lst: array of integer): integer;
begin
  var freq := new Dictionary<integer, integer>;
  foreach var num in lst do
    if freq.ContainsKey(num) then
      freq[num] += 1
    else
      freq[num] := 1;

  var maxVal := 0;
  var maxFreq := 0;
  foreach var kv in freq do
  begin
    if kv.Value > maxFreq then
    begin
      maxVal := kv.Key;
      maxFreq := kv.Value;
    end;
  end;

  if maxFreq < maxVal then
    Result := maxVal
  else
    Result := -1;
end;

begin
end.




function StrangeSortList(lst: array of integer): array of integer;
begin
  if lst.Length = 0 then
  begin
    Result := new integer[0];
    exit;
  end;

  var sorted := new List<integer>;
  var remaining := new List<integer>;

  foreach var num in lst do
    remaining.Add(num);

  remaining.Sort;

  while remaining.Count > 0 do
  begin
    sorted.Add(remaining[0]);
    remaining.RemoveAt(0);

    if remaining.Count > 0 then
    begin
      sorted.Add(remaining[remaining.Count - 1]);
      remaining.RemoveAt(remaining.Count - 1);
    end;
  end;

  Result := sorted.ToArray;
end;

begin
end.




function TriangleArea(a, b, c: real): real;
begin
  if (a + b <= c) or (b + c <= a) or (c + a <= b) then
    Result := -1
  else
  begin
    var s := a + b + c;
    var s2 := s / 2;
    var s3 := Sqrt(s2 * (s2 - a) * (s2 - b) * (s2 - c));
    Result := s3;
  end;
end;

begin
end.




