function SmallestChange(arr: array of integer): integer;
begin
  var n := arr.Length;
  var dp := new integer[n, n];

  for var i := 0 to n - 1 do
    for var j := 0 to n - 1 do
      if i = j then
        dp[i, j] := 0
      else
        dp[i, j] := 1 + dp[i + 1, j - 1];

  var ans := n;
  for var i := 0 to n - 1 do
    if dp[0, i] > dp[i, n - 1] then
      ans := i;

  Result := ans;
end;

begin
end.




