function Encrypt(s: string): string;
begin
  var encrypted := new List<char>;
  foreach var ch in s do
  begin
    if ch.IsLetter then
    begin
      var shift := 2 * Ord(ch) - 110;
      if ch.IsLower then
        encrypted.Add(char(shift mod 26 + 97))
      else
        encrypted.Add(char(shift mod 26 + 65));
    end
    else
      encrypted.Add(ch);
  end;
  Result := new string(encrypted.ToArray);
end;

begin
end.




