function Encode(message: string): string;
begin
  var encoded := new List<char>;
  var vowels := new HashSet<char>('aeiou'.!type!array of char);

  foreach var ch in message do
  begin
    if ch.IsLetter then
    begin
      if vowels.Contains(Char.ToLower(ch)) then
        encoded.Add(Char.ToUpper(ch))
      else
        encoded.Add(Char.ToLower(ch));
    end
    else
      encoded.Add(ch);
  end;

  Result := string.Join('', encoded);
end;

begin
end.




function Skjkasdkd(lst: array of integer): integer;
begin
  var primeList := new List<integer>;
  var nonPrimeList := new List<integer>;

  foreach var num in lst do
  begin
    if num = 0 then
    begin
      nonPrimeList.Add(num);
      continue;
    end;

    var isPrime := True;
    for var i := 2 to Trunc(Sqrt(num)) do
      if num mod i = 0 then
      begin
        isPrime := False;
        break;
      end;

    if isPrime then
      primeList.Add(num);
    else
      nonPrimeList.Add(num);
  end;

  var primeSum := primeList.Sum;
  var nonPrimeSum := nonPrimeList.Sum;

  Result := primeSum + nonPrimeSum;
end;

begin
end.




