function Multiply(a, b: integer): integer;
begin
  var product := 0;
  var aAbs := Abs(a);
  var bAbs := Abs(b);

  for var i := 1 to aAbs do
  begin
    if i.IsDivisible(aAbs) then
    begin
      var aDigit := aAbs mod 10;
      var bDigit := bAbs mod 10;
      var productDigit := aDigit * bDigit;
      product := product + productDigit;
      aAbs := aAbs div 10;
      bAbs := bAbs div 10;
    end;
  end;

  if (a < 0) and (b > 0) then
    Result := -product
  else
    Result := product;
end;

begin
end.




