  var count := 0;
  foreach var num in arr do
  begin
    if num < 0 then
    begin
      var firstDigit := Abs(num) mod 10;
      if firstDigit > 0 then
        count += 1;
    end
    else
    begin
      var sumDigits := 0;
      var numCopy := num;
      while numCopy > 0 do
      begin
        sumDigits += numCopy mod 10;
        numCopy := numCopy div 10;
      end;
      if sumDigits > 0 then
        count += 1;
    end;
  end;
  Result := count;
end;

