function MaxFill(grid: array of array of integer; capacity: integer): integer;
begin
  var n := grid.Length;
  var m := grid[0].Length;
  var dp := new integer[n + 1][m + 1];
  var buckets := new integer[n + 1][m + 1];

  for var i := 0 to n do
    for var j := 0 to m do
      if grid[i][j] = 1 then
      begin
        buckets[i][j] := capacity;
        if i > 0 then
          buckets[i][j] := Min(buckets[i][j], buckets[i-1][j]);
        if j > 0 then
          buckets[i][j] := Min(buckets[i][j], buckets[i][j-1]);
      end;

  for var i := 0 to n do
    for var j := 0 to m do
      if grid[i][j] = 1 then
      begin
        if i > 0 then
          dp[i][j] := dp[i-1][j] + 1;
        if j > 0 then
          dp[i][j] := Max(dp[i][j], dp[i][j-1] + 1);
      end;

  Result := dp[n][m];
end;

