begin
  var vowels := ['a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U'];
  var left := 0;
  var right := word.Length - 1;
  var closestVowel := '';

  while left < right do
  begin
    if vowels.Contains(word[left + 1]) then
    begin
      closestVowel := word[left + 1];
      break;
    end;
    left += 1;
  end;

  while left < right do
  begin
    if vowels.Contains(word[right - 1]) then
    begin
      closestVowel := word[right - 1];
      break;
    end;
    right -= 1;
  end;

  Result := closestVowel;
end;

