function Minpath(grid: array of array of integer; k: integer): array of integer;
begin
  var N := grid.Length;
  var directions := [
    (0, 1),
    (1, 0),
    (0, -1),
    (-1, 0)
  ];
  var ans := new integer[k];
  var visited := new boolean[N * N];
  var queue := new Queue<(integer, integer, integer)>;

  for var i := 0 to N - 1 do
    for var j := 0 to N - 1 do
      if visited[i * N + j] then
      begin
        queue.Enqueue((i, j, grid[i][j]));
        visited[i * N + j] := False;
      end;

  while queue.Count > 0 do
  begin
    var (i, j, val) := queue.Dequeue;

    if visited[i * N + j] then
    begin
      visited[i * N + j] := False;
      continue;
    end;

    ans[^1] := val;

    for var d := 0 to 3 do
    begin
      var ni := i + directions[d, 0];
      var nj := j + directions[d, 1];

      if (ni >= 0) and (ni < N) and (nj >= 0) and (nj < N) and 
         (not visited[ni * N + nj]) and (grid[ni][nj] < ans[^1]) then
      begin
        queue.Enqueue((ni, nj, grid[ni][nj]));
        visited[ni * N + nj] := True;
      end;
    end;
  end;

  Result := ans;
end;

begin
end.




