function DoubleTheDifference(lst: array of real): integer;
begin
  var oddSquares := new List<integer>;

  foreach var num in lst do
    if num < 0 then
      continue;
    if num <> 0 then
    begin
      var square := num * num;
      if square mod 2 <> 0 then
        oddSquares.Add(square);
    end;

  Result := oddSquares.Sum;
end;

begin
end.




function Compare(game, guess: array of integer): array of integer;
