  var ans := new List<integer>;
  for var i := 0 to game.Length - 1 do
  begin
    if game[i] = guess[i] then
      ans.Add(0)
    else
      ans.Add(!type!abs(game[i] - guess[i]));
  end;
  Result := ans.ToArray;
end;

