function FindMax(words: array of string): string;
begin
  var wordList := new List<string>(words);
  wordList.Sort;
  var maxWord := wordList[0];
  var maxWordChars := new HashSet<char>(maxWord.ToCharArray);
  var maxUnique := maxWordChars.Count;

  for var i := 1 to wordList.Count - 1 do
  begin
    var word := wordList[i];
    var wordChars := new HashSet<char>(word.ToCharArray);
    var unique := wordChars.Count;
    if unique > maxUnique then
    begin
      maxUnique := unique;
      maxWord := word;
    end;
  end;

  Result := maxWord;
end;

begin
end.




function Eat(number, need, remaining: integer): (integer, integer);
begin
  var total := number;
  var left := remaining;

  if need > left then
  begin
    total := left;
    left := 0;
  end
  else
    left := left - need;

  Result := (total, left);
end;

begin
end.




function DoAlgebra(op: array of string; operand: array of integer): integer;
begin
  var res := operand[0];
  for var i := 1 to operand.Length - 1 do
  begin
    if op[0] = '+' then
      res := res + operand[i]
    else if op[0] = '-' then
      res := res - operand[i]
    else if op[0] = '*' then
      res := res * operand[i]
    else if op[0] = '//' then
      res := res div operand[i]
    else if op[0] = '**' then
      res := res * operand[i]
    else
      raise new Exception('Invalid operator');
  end;
  Result := res;
end;

begin
end.




function Solve(s: string): string;
begin
  var chars := new List<char>;
  foreach var ch in s do
    if Char.IsLetter(ch) then
      chars.Add(Char.ToUpper(ch) * (not Char.IsLower(ch)))
    else if ch = #0 then
      chars.Add(#127);
  if chars.Any(ch -> not Char.IsLetter(ch)) then
  begin
    var reversed := chars.Reverse.ToList;
    reversed[0] := Char.ToUpper(reversed[0]);
    chars := reversed;
  end;
  Result := new string(chars.ToArray);
end;

begin
end.




